"use client";

import * as React from "react";
import { cn } from "@/lib/utils";
import { useIsPast } from "@/hooks/use-now";
import { EventDetailPopover } from "./event-detail-popover";
import { useCalendarPopoverBoundary } from "./calendar-popover-context";
import { EventContentSlot, useCalendarConfig } from "./calendar-provider";
import { formatTime, formatTimeRange, getEventLabel } from "@/lib/event-utils";
import type {
  CalendarEvent,
  CalendarEventItemProps,
  EventColor,
  EventContentProps,
  EventDetailsTriggerProps,
  EventItemPopoverProps,
  PopoverAnchorRect,
} from "./week-view-types";
import { EventContextMenu } from "./event-context-menu";

export const eventColorStyles: Record<
  EventColor,
  {
    bg: string;
    bgHover: string;
    border: string;
    borderLine: string;
    text: string;
  }
> = {
  red: {
    bg: "bg-event-red-bg",
    bgHover: "hover:bg-event-red-bg/70",
    border: "bg-event-red-border",
    borderLine: "border-event-red-border",
    text: "text-event-red",
  },
  orange: {
    bg: "bg-event-orange-bg",
    bgHover: "hover:bg-event-orange-bg/70",
    border: "bg-event-orange-border",
    borderLine: "border-event-orange-border",
    text: "text-event-orange",
  },
  yellow: {
    bg: "bg-event-yellow-bg",
    bgHover: "hover:bg-event-yellow-bg/70",
    border: "bg-event-yellow-border",
    borderLine: "border-event-yellow-border",
    text: "text-event-yellow",
  },
  green: {
    bg: "bg-event-green-bg",
    bgHover: "hover:bg-event-green-bg/70",
    border: "bg-event-green-border",
    borderLine: "border-event-green-border",
    text: "text-event-green",
  },
  blue: {
    bg: "bg-event-blue-bg",
    bgHover: "hover:bg-event-blue-bg/70",
    border: "bg-event-blue-border",
    borderLine: "border-event-blue-border",
    text: "text-event-blue",
  },
  purple: {
    bg: "bg-event-purple-bg",
    bgHover: "hover:bg-event-purple-bg/70",
    border: "bg-event-purple-border",
    borderLine: "border-event-purple-border",
    text: "text-event-purple",
  },
  gray: {
    bg: "bg-event-gray-bg",
    bgHover: "hover:bg-event-gray-bg/70",
    border: "bg-event-gray-border",
    borderLine: "border-event-gray-border",
    text: "text-event-gray",
  },
};

/**
 * Positions a block from explicit start/end times (drag and resize
 * previews), clipped to the visible hours and measured from the grid's top
 * edge (`dayStartHour`)
 */
function computeOverrideStyle(
  positionedEvent: CalendarEventItemProps["positionedEvent"],
  hourHeight: number,
  overrideStart: Date,
  overrideEnd: Date,
  dayStartHour: number,
  dayEndHour: number,
) {
  const startMinutes =
    overrideStart.getHours() * 60 + overrideStart.getMinutes();
  let endMinutes = overrideEnd.getHours() * 60 + overrideEnd.getMinutes();
  // If end is midnight and on a different day than start, treat as 1440 (end of day)
  if (endMinutes === 0 && overrideEnd.getDate() !== overrideStart.getDate()) {
    endMinutes = 1440;
  }
  const visibleStart = dayStartHour * 60;
  const visibleEnd = dayEndHour * 60;
  const topMinutes =
    Math.min(Math.max(startMinutes, visibleStart), visibleEnd) - visibleStart;
  const bottomMinutes =
    Math.min(Math.max(endMinutes, visibleStart), visibleEnd) - visibleStart;
  const topPx = (topMinutes / 60) * hourHeight;
  const heightPx = ((bottomMinutes - topMinutes) / 60) * hourHeight;

  return {
    top: `${topPx}px`,
    height: `${heightPx}px`,
    left: `${positionedEvent.left}%`,
    width: `${positionedEvent.width}%`,
    minHeight: "20px",
  };
}

const RESIZE_HOTZONE_PX = 8;

/**
 * Keyboard focus ring for events: a border on an `::after` overlay, painted
 * above the event's absolutely positioned background layers (which cover an
 * outline) and inside its box (so clipping and neighbors don't hide it).
 * Shown only for keyboard focus (`focus-visible`), never on click. The
 * event must be positioned.
 */
export const EVENT_FOCUS_RING_CLASS =
  "focus-visible:after:pointer-events-none focus-visible:after:absolute focus-visible:after:inset-0 focus-visible:after:rounded-[inherit] focus-visible:after:border-2 focus-visible:after:border-ring";

/**
 * Box for custom `renderEventContent` output in a time-grid block: above the
 * background layers, filling the block, inset like the default text
 */
const TIME_GRID_SLOT_CLASS = "relative h-full min-w-0 overflow-hidden pl-1";

interface EventDetailsTriggerOptions {
  /** Whether the event opens its details in a popover at all */
  showEventPopover: boolean;
  /** Whether the event's details popover is open */
  showPopover: boolean;
  /** The popover panel's id */
  detailsId: string;
}

/**
 * ARIA for an event element that opens the event's details in a popover:
 * what it opens, whether that is open now, and the panel it controls.
 */
export function getEventDetailsTriggerProps({
  showEventPopover,
  showPopover,
  detailsId,
}: EventDetailsTriggerOptions): EventDetailsTriggerProps {
  if (!showEventPopover) return {};
  return {
    "aria-haspopup": "dialog",
    "aria-expanded": showPopover,
    "aria-controls": showPopover ? detailsId : undefined,
  };
}

interface EventDetailsToggleOptions {
  /** Whether the event's details popover is open */
  showPopover: boolean;
  /** Whether the event opens its details in a popover at all */
  showEventPopover: boolean;
  close: () => void;
}

/**
 * An event opens and closes its details popover. Gives the event element the
 * popup's ARIA and keeps its click a toggle: a mouse press selects the event,
 * and so opens the details, before its click arrives, so the click closes
 * them only when they were already open at the press.
 */
function useEventDetailsToggle({
  showPopover,
  showEventPopover,
  close,
}: EventDetailsToggleOptions) {
  const detailsId = React.useId();
  /** Whether the details were open when the current press began */
  const openOnPressRef = React.useRef<boolean | null>(null);

  return {
    detailsId,
    /** For the event element, which opens the details, a dialog */
    triggerProps: getEventDetailsTriggerProps({
      showEventPopover,
      showPopover,
      detailsId,
    }),
    /** Call when a press on the event begins */
    notePress() {
      openOnPressRef.current = showPopover;
    },
    /** Call from the event's click, after it selected the event */
    closeIfToggled() {
      // A click with no press before it (assistive technology) toggles too
      const wasOpen = openOnPressRef.current ?? showPopover;
      openOnPressRef.current = null;
      if (wasOpen && showPopover) close();
    },
  };
}

export function CalendarEventItem({
  positionedEvent,
  hourHeight,
  isPast: isPastProp,
  isSelected,
  onClick,
  dragVariant = "default",
  isResizing = false,
  overrideStart,
  overrideEnd,
  onDragPointerDown,
  onResizePointerDown,
  onEventChange,
  cursorY,
  cursorX,
  fixedWidth,
  fixedHeight,
  onContextMenuOpenChange,
  showEventPopover,
  onEventPopoverExpand,
  onEventPopoverClose,
  onPrevWeek,
  onNextWeek,
  className,
}: CalendarEventItemProps) {
  const { event, segmentPosition = "full" } = positionedEvent;
  const color = event.color ?? "blue";
  const styles = eventColorStyles[color];
  // `false` on the server and during hydration, so the markup matches
  const endIsPast = useIsPast(event.end);
  const eventIsPast = isPastProp ?? endIsPast;
  const { view, boundaryRight, headerBottom } = useCalendarPopoverBoundary();
  const { dayStartHour, dayEndHour, hourCycle, locale } = useCalendarConfig();
  const isDayView = view === "day";

  /** Ref to the event button element, used to measure its viewport rect. */
  const eventRef = React.useRef<HTMLDivElement>(null);

  /**
   * Viewport-relative top & height of the event element.
   * Used to vertically align the day-view popover anchor with the event
   * so the popover appears beside the event rather than at a fixed position.
   */
  const [anchorRect, setAnchorRect] = React.useState<{
    top: number;
    height: number;
  } | null>(null);

  const showPopover = isSelected && showEventPopover;
  const detailsToggle = useEventDetailsToggle({
    showPopover: showPopover ?? false,
    showEventPopover: showEventPopover ?? false,
    close: () => onEventPopoverClose?.(event.id),
  });

  // Measure the event element's viewport position when the popover opens in
  // day view. useLayoutEffect ensures the measurement happens before paint so
  // the popover anchor is positioned correctly on first frame.
  React.useLayoutEffect(() => {
    if (!showPopover || !isDayView || !eventRef.current) {
      setAnchorRect(null);
      return;
    }
    const rect = eventRef.current.getBoundingClientRect();
    setAnchorRect({ top: rect.top, height: rect.height });
  }, [showPopover, isDayView]);

  /**
   * In day view the event spans the full grid width, so there is no room for
   * the popover beside it. Anchor it to a zero-width line at the RIGHT edge
   * of the calendar boundary, level with the event, and open it leftward
   * (side="left") — matching Notion Calendar.
   */
  const dayViewAnchor = React.useMemo<PopoverAnchorRect>(
    () => ({
      getBoundingClientRect: () =>
        new DOMRect(
          boundaryRight,
          anchorRect?.top ?? 0,
          0,
          anchorRect?.height ?? 0,
        ),
    }),
    [boundaryRight, anchorRect],
  );

  const hasTopRounding =
    segmentPosition === "start" || segmentPosition === "full";
  const hasBottomRounding =
    segmentPosition === "end" || segmentPosition === "full";
  const showTopResize =
    segmentPosition === "start" || segmentPosition === "full";
  const showBottomResize =
    segmentPosition === "end" || segmentPosition === "full";

  const [contextMenu, setContextMenu] = React.useState<{
    x: number;
    y: number;
  } | null>(null);

  const closeContextMenu = React.useCallback(() => {
    setContextMenu(null);
    onContextMenuOpenChange?.(false);
  }, [onContextMenuOpenChange]);

  const displayStart = overrideStart ?? event.start;
  const displayEnd = overrideEnd ?? event.end;

  const displayEvent: CalendarEvent =
    overrideStart && overrideEnd
      ? { ...event, start: displayStart, end: displayEnd }
      : event;

  const defaultStyle = {
    top: `${positionedEvent.top}%`,
    height: `${positionedEvent.height}%`,
    left: `${positionedEvent.left}%`,
    width: `${positionedEvent.width}%`,
    minHeight: "20px",
    zIndex: isSelected ? 20 : positionedEvent.column,
  };

  const posStyle =
    overrideStart && overrideEnd
      ? computeOverrideStyle(
          positionedEvent,
          hourHeight,
          overrideStart,
          overrideEnd,
          dayStartHour,
          dayEndHour,
        )
      : defaultStyle;

  const heightInPixels =
    overrideStart && overrideEnd
      ? Number.parseFloat(String(posStyle.height))
      : (positionedEvent.height / 100) *
        (dayEndHour - dayStartHour) *
        hourHeight;
  const isCompact = heightInPixels < 40;
  /**
   * A resize preview drawn next to the real event (its anchor or another
   * day's segment), not an event the user can focus
   */
  const isPreview = isResizing || Boolean(overrideStart && overrideEnd);
  const timeRangeLabel = formatTimeRange(
    displayEvent.start,
    displayEvent.end,
    hourCycle,
    locale,
  );

  const contentProps: EventContentProps = {
    event: displayEvent,
    view,
    placement: "time-grid",
    isSelected: isSelected ?? false,
    isPast: eventIsPast,
    isDragging: dragVariant === "dragging",
    isResizing,
    isCompact,
    timeLabel: timeRangeLabel,
  };

  if (dragVariant === "ghost") {
    return (
      <div
        aria-hidden
        className={cn(
          "absolute rounded-sm px-2 py-1 pointer-events-none opacity-30 overflow-hidden",
          className,
        )}
        style={{
          top: `${positionedEvent.top}%`,
          height: `${positionedEvent.height}%`,
          left: `${positionedEvent.left}%`,
          width: `${positionedEvent.width}%`,
          minHeight: "20px",
          zIndex: 15,
        }}
      >
        <div className="absolute inset-0 rounded-sm bg-white dark:bg-[#191919]" />
        <div className={cn("absolute inset-0 rounded-sm", styles.bg)} />
        <div
          className={cn(
            "absolute left-0 top-0 bottom-0 w-[4px] rounded-l-md dark:bg-white dark:mix-blend-overlay",
            styles.border,
          )}
        />
        <EventContentSlot
          {...contentProps}
          className={TIME_GRID_SLOT_CLASS}
          fallback={
            <div
              className={cn(
                "relative flex flex-col h-full pl-1 overflow-hidden",
                isCompact && "flex-row items-center gap-1",
              )}
            >
              <span
                className={cn(
                  "font-medium text-[0.625rem] leading-tight break-words",
                  styles.text,
                  "dark:text-white/80",
                )}
              >
                {event.title}
              </span>
              {!isCompact && (
                <span
                  className={cn(
                    "text-[0.625rem] whitespace-nowrap",
                    styles.text,
                    "dark:text-white dark:mix-blend-overlay",
                  )}
                >
                  {formatTimeRange(event.start, event.end, hourCycle, locale)}
                </span>
              )}
            </div>
          }
        />
      </div>
    );
  }

  if (dragVariant === "placeholder") {
    return (
      <div
        aria-hidden
        className={cn(
          "absolute rounded-sm pointer-events-none border-2",
          styles.borderLine,
          className,
        )}
        style={{
          ...posStyle,
          left: "0%",
          width: "100%",
          zIndex: 25,
        }}
      />
    );
  }

  const isDraggingCopy = dragVariant === "dragging";

  if (isDraggingCopy) {
    const durationMinutes =
      (displayEnd.getTime() - displayStart.getTime()) / 60000;
    const heightPx = fixedHeight ?? (durationMinutes / 60) * hourHeight;

    const useFixed = cursorX != null && cursorY != null;

    const draggingStyle: React.CSSProperties = useFixed
      ? {
          position: "fixed",
          top: `${cursorY}px`,
          left: `${cursorX}px`,
          height: `${heightPx}px`,
          width: fixedWidth != null ? `${fixedWidth}px` : "200px",
          minHeight: "20px",
          zIndex: 30,
        }
      : {
          top: posStyle.top,
          height: `${heightPx}px`,
          left: `${positionedEvent.left}%`,
          width: `${positionedEvent.width}%`,
          minHeight: "20px",
          zIndex: 30,
        };

    return (
      <div
        tabIndex={-1}
        aria-hidden
        className={cn(
          "absolute rounded-sm px-2 py-1",
          "pointer-events-none cursor-grabbing",
          "overflow-hidden select-none opacity-80 shadow-lg",
          className,
        )}
        style={draggingStyle}
      >
        <div className="absolute inset-0 rounded-sm bg-white dark:bg-[#191919]" />
        <div className={cn("absolute inset-0 rounded-sm", styles.bg)} />
        <div
          className={cn(
            "absolute left-0 top-0 bottom-0 w-[4px] rounded-l-md dark:bg-white dark:mix-blend-overlay",
            styles.border,
          )}
        />
        <EventContentSlot
          {...contentProps}
          isCompact={heightPx < 40}
          className={TIME_GRID_SLOT_CLASS}
          fallback={
            <div
              className={cn(
                "relative flex flex-col h-full pl-1 overflow-hidden",
                heightPx < 40 && "flex-row items-center gap-1",
              )}
            >
              <span className="font-medium text-[0.625rem] leading-tight break-words text-white dark:text-white flex items-center gap-0.5">
                {event.title}
              </span>
              {heightPx >= 40 && (
                <span className="text-[0.625rem] whitespace-nowrap text-white dark:text-white">
                  {timeRangeLabel}
                </span>
              )}
            </div>
          }
        />
      </div>
    );
  }

  function handleMouseMove(e: React.MouseEvent) {
    const target = e.currentTarget as HTMLElement;
    const rect = target.getBoundingClientRect();
    const offsetY = e.clientY - rect.top;
    const height = rect.height;

    if (showTopResize && showBottomResize && height < RESIZE_HOTZONE_PX * 2) {
      target.style.setProperty("--cursor", "row-resize");
      return;
    }

    if (showTopResize && offsetY <= RESIZE_HOTZONE_PX) {
      target.style.setProperty("--cursor", "row-resize");
      return;
    }

    if (showBottomResize && offsetY >= height - RESIZE_HOTZONE_PX) {
      target.style.setProperty("--cursor", "row-resize");
      return;
    }

    target.style.removeProperty("--cursor");
  }

  function handlePointerDown(e: React.PointerEvent<HTMLElement>) {
    e.stopPropagation();
    detailsToggle.notePress();

    const rect = e.currentTarget.getBoundingClientRect();
    const offsetY = e.clientY - rect.top;
    const height = rect.height;

    if (showTopResize && showBottomResize && height < RESIZE_HOTZONE_PX * 2) {
      const edge = offsetY < height / 2 ? "top" : "bottom";
      onResizePointerDown?.(e, event, edge);
      return;
    }

    if (showTopResize && offsetY <= RESIZE_HOTZONE_PX) {
      onResizePointerDown?.(e, event, "top");
      return;
    }

    if (showBottomResize && offsetY >= height - RESIZE_HOTZONE_PX) {
      onResizePointerDown?.(e, event, "bottom");
      return;
    }

    onDragPointerDown?.(e, event);
  }

  function handleClick(e: React.MouseEvent) {
    e.stopPropagation();
    onClick?.(event);
    detailsToggle.closeIfToggled();
  }

  function handleKeyDown(e: React.KeyboardEvent) {
    if (e.key !== "Enter" && e.key !== " ") return;
    e.preventDefault();
    onClick?.(event);
  }

  function handleContextMenu(e: React.MouseEvent) {
    e.preventDefault();
    e.stopPropagation();
    setContextMenu({ x: e.clientX, y: e.clientY });
    onContextMenuOpenChange?.(true);
  }

  const eventElement = (
    <div
      ref={eventRef}
      role="button"
      tabIndex={isPreview ? -1 : 0}
      aria-hidden={isPreview || undefined}
      aria-label={getEventLabel(event, hourCycle, locale)}
      aria-pressed={isSelected ?? false}
      {...(!isPreview && detailsToggle.triggerProps)}
      data-event-id={isPreview ? undefined : event.id}
      onPointerDown={handlePointerDown}
      onMouseMove={handleMouseMove}
      onClick={handleClick}
      onKeyDown={handleKeyDown}
      onContextMenu={handleContextMenu}
      className={cn(
        "absolute px-2 py-1",
        hasTopRounding && "rounded-t-md",
        hasBottomRounding && "rounded-b-md",
        "cursor-default hover:z-10 focus:outline-none",
        EVENT_FOCUS_RING_CLASS,
        "overflow-hidden select-none",
        isSelected && "z-20",
        className,
      )}
      style={{
        ...posStyle,
        zIndex: isSelected ? 20 : positionedEvent.column,
      }}
    >
      {/* Solid background layer to prevent transparency bleed-through */}
      <div
        className={cn(
          "absolute inset-0 bg-white dark:bg-[#191919]",
          hasTopRounding && "rounded-t-md",
          hasBottomRounding && "rounded-b-md",
        )}
      />

      {/* Colored background layer - uses border color when selected */}
      <div
        className={cn(
          "absolute inset-0",
          hasTopRounding && "rounded-t-md",
          hasBottomRounding && "rounded-b-md",
          isSelected ? styles.border : styles.bg,
          eventIsPast && !isSelected && "opacity-60",
        )}
      />

      {/* Left border - hidden when selected (merges with bg) */}
      {!isSelected && (
        <div
          className={cn(
            "absolute left-0 top-0 bottom-0 w-[4px] dark:bg-white dark:mix-blend-overlay",
            hasTopRounding && "rounded-tl-md",
            hasBottomRounding && "rounded-bl-md",
            styles.border,
            eventIsPast && "opacity-60",
          )}
        />
      )}
      <EventContentSlot
        {...contentProps}
        className={TIME_GRID_SLOT_CLASS}
        fallback={
          <div
            className={cn(
              "relative flex flex-col h-full pl-1 overflow-hidden",
              isCompact && "flex-row items-center gap-1",
            )}
          >
            <span
              className={cn(
                "font-medium text-[0.625rem] leading-tight break-words flex items-center gap-0.5",
                isSelected
                  ? "text-white dark:text-white"
                  : cn(
                      styles.text,
                      "dark:text-white/80",
                      eventIsPast && "opacity-60",
                    ),
              )}
            >
              {event.title}
            </span>
            {!isCompact && (
              <span
                className={cn(
                  "text-[0.625rem] whitespace-nowrap",
                  isSelected
                    ? "text-white dark:text-white"
                    : cn(
                        styles.text,
                        "dark:text-white dark:mix-blend-overlay",
                        eventIsPast && "opacity-60 dark:opacity-100",
                      ),
                )}
              >
                {timeRangeLabel}
              </span>
            )}
          </div>
        }
      />
    </div>
  );

  return (
    <>
      {eventElement}
      {showPopover && (
        <EventDetailPopover
          event={event}
          id={detailsToggle.detailsId}
          anchor={isDayView ? dayViewAnchor : eventRef}
          triggerRef={eventRef}
          onEventChange={onEventChange}
          onClose={() => onEventPopoverClose?.(event.id)}
          onExpand={onEventPopoverExpand}
          onPrevWeek={onPrevWeek}
          onNextWeek={onNextWeek}
          side={isDayView ? "left" : "right"}
          collisionPaddingTop={isDayView ? headerBottom : undefined}
        />
      )}
      {contextMenu && (
        <EventContextMenu
          event={event}
          position={contextMenu}
          onClose={closeContextMenu}
          onEventChange={onEventChange}
        />
      )}
    </>
  );
}

/** Drag visual variant for all-day events */
export type AllDayDragVariant = "ghost" | "placeholder" | "dragging";

export interface AllDayEventItemProps extends EventItemPopoverProps {
  event: CalendarEvent;
  /** Overrides whether the event renders as past (defaults to `useIsPast`) */
  isPast?: boolean;
  isSelected?: boolean;
  onClick?: (event: CalendarEvent) => void;
  className?: string;
  /** For multi-day events: position info */
  spanStart?: boolean;
  spanEnd?: boolean;
  /** Pointerdown handler to initiate horizontal resize or drag */
  onResizePointerDown?: (
    e: React.PointerEvent<HTMLElement>,
    event: CalendarEvent,
    edge: "left" | "right" | "move",
  ) => void;
  /** Callback when an event is changed (e.g. color change from context menu) */
  onEventChange?: (event: CalendarEvent) => void;
  /** Callback when context menu open state changes */
  onContextMenuOpenChange?: (open: boolean) => void;
  /**
   * Percentage of the event's width that is hidden off-screen to the left.
   * Used in day view to offset the title into the visible area so multi-day
   * events always show their title \u2014 \u201csticky title\u201d effect.
   */
  titleOffsetPercent?: number;
  /** Visual variant during drag operations */
  dragVariant?: AllDayDragVariant;
  /** Whether the event's edges are being dragged (passed to `renderEventContent`) */
  isResizing?: boolean;
}

const ALL_DAY_RESIZE_HOTZONE_PX = 6;

/**
 * Box for custom `renderEventContent` output in an all-day bar: above the
 * background layers, filling the bar (`pl-1` is added beside the left accent)
 */
const ALL_DAY_SLOT_CLASS =
  "relative flex h-full min-w-0 flex-1 items-center overflow-hidden";

export function AllDayEventItem({
  event,
  isPast: isPastProp,
  isSelected,
  onClick,
  className,
  spanStart = true,
  spanEnd = true,
  onResizePointerDown,
  onEventChange,
  onContextMenuOpenChange,
  showEventPopover,
  onEventPopoverExpand,
  onEventPopoverClose,
  onPrevWeek,
  onNextWeek,
  titleOffsetPercent = 0,
  dragVariant,
  isResizing = false,
}: AllDayEventItemProps) {
  const color = event.color ?? "blue";
  const styles = eventColorStyles[color];
  const { view, boundaryRight, headerBottom } = useCalendarPopoverBoundary();
  const { hourCycle, locale } = useCalendarConfig();
  const isDayView = view === "day";
  // `false` on the server and during hydration, so the markup matches
  const endIsPast = useIsPast(event.end);
  const eventIsPast = isPastProp ?? endIsPast;

  /** The event element: anchors and toggles its details popover */
  const eventRef = React.useRef<HTMLDivElement>(null);
  const showPopover = isSelected && showEventPopover;
  const detailsToggle = useEventDetailsToggle({
    showPopover: showPopover ?? false,
    showEventPopover: showEventPopover ?? false,
    close: () => onEventPopoverClose?.(event.id),
  });

  /**
   * In day view, all-day events span the full width. Anchor the popover to
   * the calendar boundary's right edge (a zero-width line the height of the
   * viewport) so it always appears at the visible right edge — even when the
   * event wrapper extends into off-screen buffer days.
   */
  const dayViewAnchor = React.useMemo<PopoverAnchorRect>(
    () => ({
      getBoundingClientRect: () =>
        new DOMRect(boundaryRight, 0, 0, window.innerHeight),
    }),
    [boundaryRight],
  );

  const [contextMenu, setContextMenu] = React.useState<{
    x: number;
    y: number;
  } | null>(null);

  const closeContextMenu = React.useCallback(() => {
    setContextMenu(null);
    onContextMenuOpenChange?.(false);
  }, [onContextMenuOpenChange]);

  // Check if event has a specific start time (not midnight)
  const hasStartTime =
    event.start.getHours() !== 0 || event.start.getMinutes() !== 0;
  // "8:45 AM" / "4 PM", or "08:45" / "16:00" on a 24-hour clock
  const startTimeLabel = hasStartTime
    ? formatTime(event.start, hourCycle, locale)
    : "";

  const contentProps: EventContentProps = {
    event,
    view,
    placement: "all-day",
    isSelected: isSelected ?? false,
    isPast: eventIsPast,
    isDragging: dragVariant === "dragging",
    isResizing,
    isCompact: true,
    timeLabel: startTimeLabel,
  };
  const slotClassName = cn(ALL_DAY_SLOT_CLASS, spanStart && "pl-1");

  // Ghost: faded version at original position during move
  if (dragVariant === "ghost") {
    return (
      <div
        aria-hidden
        className={cn(
          "relative h-6 px-2 py-0.5 pointer-events-none opacity-30",
          "overflow-hidden select-none flex items-center gap-1",
          spanStart && "rounded-l-md",
          spanEnd && "rounded-r-md",
          className,
        )}
      >
        <div
          className={cn(
            "absolute inset-0 bg-white dark:bg-[#191919]",
            spanStart && "rounded-l-md",
            spanEnd && "rounded-r-md",
          )}
        />
        <div
          className={cn(
            "absolute inset-0",
            styles.bg,
            spanStart && "rounded-l-md",
            spanEnd && "rounded-r-md",
          )}
        />
        {spanStart && (
          <div
            className={cn(
              "absolute left-0 top-0 bottom-0 w-[4px] dark:bg-white dark:mix-blend-overlay",
              spanStart && "rounded-l-md",
              styles.border,
            )}
          />
        )}
        <EventContentSlot
          {...contentProps}
          className={slotClassName}
          fallback={
            <span
              className={cn(
                "relative font-medium text-[0.625rem] leading-tight whitespace-nowrap",
                spanStart && "pl-1",
                styles.text,
                "dark:text-white/80",
              )}
            >
              {event.title}
            </span>
          }
        />
      </div>
    );
  }

  // Placeholder: border-only outline at target position
  if (dragVariant === "placeholder") {
    return (
      <div
        aria-hidden
        className={cn(
          "relative h-6 pointer-events-none border-2 rounded-sm",
          styles.borderLine,
          className,
        )}
      />
    );
  }

  // Dragging copy: floating replica following cursor
  if (dragVariant === "dragging") {
    return (
      <div
        aria-hidden
        className={cn(
          "h-6 px-2 py-0.5 pointer-events-none cursor-grabbing",
          "overflow-hidden select-none flex items-center gap-1",
          "rounded-sm opacity-80 shadow-lg",
          className,
        )}
      >
        <div className="absolute inset-0 rounded-sm bg-white dark:bg-[#191919]" />
        <div className={cn("absolute inset-0 rounded-sm", styles.bg)} />
        <div
          className={cn(
            "absolute left-0 top-0 bottom-0 w-[4px] rounded-l-md dark:bg-white dark:mix-blend-overlay",
            styles.border,
          )}
        />
        <EventContentSlot
          {...contentProps}
          className={slotClassName}
          fallback={
            <span
              className={cn(
                "relative font-medium text-[0.625rem] leading-tight whitespace-nowrap pl-1",
                styles.text,
                "dark:text-white/80",
              )}
            >
              {event.title}
            </span>
          }
        />
      </div>
    );
  }

  function handleClick(e: React.MouseEvent) {
    e.stopPropagation();
    onClick?.(event);
    detailsToggle.closeIfToggled();
  }

  function handleKeyDown(e: React.KeyboardEvent) {
    if (e.key !== "Enter" && e.key !== " ") {
      return;
    }
    e.preventDefault();
    onClick?.(event);
  }

  function handleAllDayMouseMove(e: React.MouseEvent) {
    const target = e.currentTarget as HTMLElement;
    const rect = target.getBoundingClientRect();
    const offsetX = e.clientX - rect.left;
    const width = rect.width;

    if (spanStart && offsetX <= ALL_DAY_RESIZE_HOTZONE_PX) {
      target.style.setProperty("--cursor", "col-resize");
      return;
    }

    if (spanEnd && offsetX >= width - ALL_DAY_RESIZE_HOTZONE_PX) {
      target.style.setProperty("--cursor", "col-resize");
      return;
    }

    target.style.removeProperty("--cursor");
  }

  function handleAllDayPointerDown(e: React.PointerEvent<HTMLElement>) {
    detailsToggle.notePress();
    if (!onResizePointerDown) return;

    const rect = e.currentTarget.getBoundingClientRect();
    const offsetX = e.clientX - rect.left;
    const width = rect.width;

    if (spanStart && offsetX <= ALL_DAY_RESIZE_HOTZONE_PX) {
      e.stopPropagation();
      onResizePointerDown(e, event, "left");
      return;
    }

    if (spanEnd && offsetX >= width - ALL_DAY_RESIZE_HOTZONE_PX) {
      e.stopPropagation();
      onResizePointerDown(e, event, "right");
      return;
    }

    // Middle area: initiate drag (move)
    e.stopPropagation();
    onResizePointerDown(e, event, "move");
  }

  function handleContextMenu(e: React.MouseEvent) {
    e.preventDefault();
    e.stopPropagation();
    setContextMenu({ x: e.clientX, y: e.clientY });
    onContextMenuOpenChange?.(true);
  }

  const eventElement = (
    <div
      ref={eventRef}
      role="button"
      tabIndex={0}
      aria-label={getEventLabel(event, hourCycle, locale)}
      aria-pressed={isSelected ?? false}
      {...detailsToggle.triggerProps}
      data-event-id={event.id}
      onClick={handleClick}
      onKeyDown={handleKeyDown}
      onContextMenu={handleContextMenu}
      onMouseMove={handleAllDayMouseMove}
      onPointerDown={handleAllDayPointerDown}
      className={cn(
        "relative h-6 px-2 py-0.5 cursor-default",
        "hover:z-10 focus:outline-none",
        EVENT_FOCUS_RING_CLASS,
        "overflow-hidden select-none flex items-center gap-1",
        spanStart && "rounded-l-md",
        spanEnd && "rounded-r-md",
        isSelected && "z-20",
        className,
      )}
      style={
        titleOffsetPercent > 0
          ? { paddingLeft: `${titleOffsetPercent}%` }
          : undefined
      }
    >
      {/* Solid background layer to prevent transparency bleed-through */}
      <div
        className={cn(
          "absolute inset-0 bg-white dark:bg-[#191919]",
          spanStart && "rounded-l-md",
          spanEnd && "rounded-r-md",
        )}
      />

      {/* Colored background layer - uses border color when selected */}
      <div
        className={cn(
          "absolute inset-0",
          isSelected ? styles.border : styles.bg,
          spanStart && "rounded-l-md",
          spanEnd && "rounded-r-md",
          eventIsPast && !isSelected && "opacity-60",
        )}
      />

      {/* Left border - hidden when selected (merges with bg) */}
      {spanStart && !isSelected && (
        <div
          className={cn(
            "absolute left-0 top-0 bottom-0 w-[4px] dark:bg-white dark:mix-blend-overlay",
            spanStart && "rounded-l-md",
            styles.border,
            eventIsPast && "opacity-60",
          )}
        />
      )}
      <EventContentSlot
        {...contentProps}
        className={slotClassName}
        fallback={
          <>
            <span
              className={cn(
                "relative font-medium text-[0.625rem] leading-tight whitespace-nowrap",
                spanStart && "pl-1",
                isSelected
                  ? "text-white dark:text-white"
                  : cn(
                      styles.text,
                      "dark:text-white/80",
                      eventIsPast && "opacity-60",
                    ),
              )}
            >
              {event.title}
            </span>
            {hasStartTime && (
              <span
                className={cn(
                  "relative text-[0.625rem] leading-tight whitespace-nowrap shrink-0",
                  isSelected
                    ? "text-white dark:text-white"
                    : cn(
                        styles.text,
                        "dark:text-white dark:mix-blend-overlay",
                        eventIsPast && "opacity-60",
                      ),
                )}
              >
                {startTimeLabel}
              </span>
            )}
          </>
        }
      />
    </div>
  );

  return (
    <>
      {eventElement}
      {showPopover && (
        <EventDetailPopover
          event={event}
          id={detailsToggle.detailsId}
          anchor={isDayView ? dayViewAnchor : eventRef}
          triggerRef={eventRef}
          onEventChange={onEventChange}
          onClose={() => onEventPopoverClose?.(event.id)}
          onExpand={onEventPopoverExpand}
          onPrevWeek={onPrevWeek}
          onNextWeek={onNextWeek}
          side={isDayView ? "left" : "right"}
          align="start"
          collisionPaddingTop={isDayView ? headerBottom : undefined}
        />
      )}
      {contextMenu && (
        <EventContextMenu
          event={event}
          position={contextMenu}
          onClose={closeContextMenu}
          onEventChange={onEventChange}
        />
      )}
    </>
  );
}

"use client";

import * as React from "react";
import * as ReactDOM from "react-dom";
import {
  Check,
  ChevronDown,
  CircleHelp,
  Copy,
  MoreHorizontal,
  SquareDashed,
  TabletSmartphone,
  Trash2,
} from "lucide-react";

import { cn } from "@/lib/utils";
import { useInlineEdit } from "@/hooks/use-inline-edit";
import { Button } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuShortcut,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { EventDetailAiNotes } from "./event-detail-ai-notes";
import { EventDetailAvailability } from "./event-detail-availability";
import { EventDetailCalendar } from "./event-detail-calendar";
import { EventDetailConferencing } from "./event-detail-conferencing";
import { EventDetailDescription } from "./event-detail-description";
import { EventDetailLinks } from "./event-detail-links";
import { EventDetailLocation } from "./event-detail-location";
import {
  EVENT_DETAIL_HOVER_BORDER_CLASS,
  EVENT_DETAIL_ICON_BUTTON_CLASS,
  EVENT_DETAIL_INPUT_CLASS,
  EVENT_DETAIL_MENU_CLASS,
  EVENT_DETAIL_MENU_ITEM_CLASS,
  EVENT_DETAIL_MUTED_CLASS,
  EVENT_DETAIL_PLACEHOLDER_CLASS,
  EVENT_DETAIL_ROW_HEIGHT_CLASS,
  EVENT_DETAIL_SECONDARY_CLASS,
  EVENT_DETAIL_TEXT_CLASS,
  EventDetailDivider,
  EventDetailGroup,
  closeMenuOnEscape,
  stopEscapePropagation,
} from "./event-detail-parts";
import { EventDetailParticipants } from "./event-detail-participants";
import { EventDetailRecurrence } from "./event-detail-recurrence";
import { EventDetailReminders } from "./event-detail-reminders";
import { EventDetailAllDay, EventDetailTime } from "./event-detail-time";
import { EventDetailTimezone } from "./event-detail-timezone";
import type { DetailedCalendarEvent, EventKind } from "./week-view-types";

/**
 * Props for EventDetailPanel. `TEvent` is the app's event type; detail fields
 * it doesn't set show placeholders, and edits keep its other fields.
 */
interface EventDetailPanelProps<
  TEvent extends DetailedCalendarEvent = DetailedCalendarEvent,
> {
  event: TEvent;
  onEventChange?: (event: TEvent) => void;
  /** Shows the previous event of a repeating series */
  onPrevWeek?: () => void;
  /** Shows the next event of a repeating series */
  onNextWeek?: () => void;
  /** Extra action buttons rendered in the header row (after the "..." menu). */
  headerActions?: React.ReactNode;
  /** When true, focuses and selects the title input once (e.g. for a just-created event). */
  autoFocusTitle?: boolean;
  /** Called after the title input was auto-focused, so the request is not repeated. */
  onTitleAutoFocused?: () => void;
}

/** Event kinds in the header menu's order */
const EVENT_KINDS: EventKind[] = [
  "event",
  "focus-time",
  "out-of-office",
  "birthday",
];

/** Name of each event kind in the header menu */
const EVENT_KIND_LABELS: Record<EventKind, string> = {
  event: "Event",
  "focus-time": "Focus time",
  "out-of-office": "Out of office",
  birthday: "Birthday",
};

/** Help shown beside a kind in the header menu */
const EVENT_KIND_TOOLTIPS: Partial<Record<EventKind, string>> = {
  "focus-time":
    "Create a focus time event with the option to automatically decline meetings during this time. Available for work and school accounts.",
  "out-of-office":
    "Create an out of office (OOO) event with the option to automatically decline meetings during this time. Available for work and school accounts.",
  birthday:
    "Create a birthday event to keep track of a person's upcoming birthdays. Birthdays from your Google Contacts may appear on a separate Birthday calendar.",
};

function EventKindHelpIcon({ tooltip }: { tooltip?: string }) {
  const [tooltipPos, setTooltipPos] = React.useState<{
    top: number;
    left: number;
  } | null>(null);

  if (!tooltip) {
    return null;
  }

  function handleMouseEnter(e: React.MouseEvent<HTMLSpanElement>) {
    const rect = e.currentTarget.getBoundingClientRect();
    setTooltipPos({ top: rect.top + rect.height / 2, left: rect.left });
  }

  function handleMouseLeave() {
    setTooltipPos(null);
  }

  return (
    <span
      className="ml-auto shrink-0 opacity-0 group-hover/item:opacity-100 transition-opacity"
      onClick={(e) => e.stopPropagation()}
      onPointerDown={(e) => e.stopPropagation()}
      onMouseEnter={handleMouseEnter}
      onMouseLeave={handleMouseLeave}
    >
      <CircleHelp className="size-3.5 text-white" />
      {tooltipPos &&
        ReactDOM.createPortal(
          <div
            className="pointer-events-none fixed z-[100] max-w-[240px] rounded-sm bg-[#252525] border border-[#303030] px-2 py-1 text-xs text-white shadow-md"
            style={{
              top: tooltipPos.top,
              left: tooltipPos.left - 8,
              transform: "translate(-100%, -50%)",
            }}
          >
            {tooltip}
          </div>,
          document.body,
        )}
    </span>
  );
}

/**
 * The muted "All-day  Time zone  Repeat" line a plain timed event shows
 * under its date. Clicking it opens the three rows.
 */
function EventDetailOptionsRow({ onExpand }: { onExpand: () => void }) {
  const labelClass = cn(
    EVENT_DETAIL_PLACEHOLDER_CLASS,
    "group-hover/options:text-[#A5A5A5] dark:group-hover/options:text-[#636363]",
  );

  return (
    <div
      className={cn(
        "flex items-center pl-[36px]",
        EVENT_DETAIL_ROW_HEIGHT_CLASS,
      )}
    >
      <div
        className="group/options flex h-[31px] cursor-default items-center gap-[18px] rounded-md px-[9px] hover:bg-[#F5F5F5] dark:hover:bg-[#242424]"
        onClick={onExpand}
      >
        <span className={labelClass}>All-day</span>
        <span className={labelClass}>Time zone</span>
        <span className={labelClass}>Repeat</span>
      </div>
    </div>
  );
}

/**
 * Notion Calendar-style event details: the kind menu, the title, then one
 * section per field (time, time zone, repeat, participants, conferencing,
 * AI notes, location, links, description, calendar, availability,
 * reminders) in Notion's order and groups. Each section edits its own
 * fields through `onEventChange`.
 */
export function EventDetailPanel<
  TEvent extends DetailedCalendarEvent = DetailedCalendarEvent,
>({
  event,
  onEventChange,
  onPrevWeek,
  onNextWeek,
  headerActions,
  autoFocusTitle,
  onTitleAutoFocused,
}: EventDetailPanelProps<TEvent>) {
  const kind = event.kind ?? "event";
  const [kindMenuOpen, setKindMenuOpen] = React.useState(false);
  const [hoveredOther, setHoveredOther] = React.useState(false);
  /** Whether the compact "All-day / Time zone / Repeat" row is expanded into individual rows. */
  const [optionsExpanded, setOptionsExpanded] = React.useState(false);

  const titleRef = React.useRef<HTMLInputElement>(null);
  const title = useInlineEdit({
    inputRef: titleRef,
    value: event.title,
    onInput: (text) => onEventChange?.({ ...event, title: text }),
    onRestore: (text) => onEventChange?.({ ...event, title: text }),
    onCommit: (text) => {
      const trimmed = text.trim();
      // Only spaces: back to the title from before editing. Deleting the
      // whole title still clears it.
      if (text && !trimmed) return null;
      if (trimmed !== text) onEventChange?.({ ...event, title: trimmed });
      return trimmed;
    },
  });

  // Reset expanded options when switching to a different event
  React.useEffect(() => {
    setOptionsExpanded(false);
  }, [event.id]);

  // Focus + select the title on request so a new event can be named right away.
  // Deferred a frame so a popover host has been positioned before focusing.
  React.useEffect(() => {
    if (!autoFocusTitle) return;
    const frame = requestAnimationFrame(() => {
      titleRef.current?.focus({ preventScroll: true });
      titleRef.current?.select();
      onTitleAutoFocused?.();
    });
    return () => cancelAnimationFrame(frame);
  }, [autoFocusTitle, onTitleAutoFocused, titleRef]);

  const selectKind = (next: EventKind) => {
    if (next === kind) return;
    onEventChange?.({ ...event, kind: next });
  };

  const otherKinds = EVENT_KINDS.filter((k) => k !== kind);
  const showOptionRows =
    optionsExpanded ||
    event.isAllDay ||
    Boolean(
      event.recurrenceRule ??
      event.recurrence ??
      event.timeZone ??
      event.timezone,
    );

  return (
    <div
      className={cn(
        "flex flex-col pt-3 text-sm font-medium",
        EVENT_DETAIL_TEXT_CLASS,
      )}
    >
      {/* Header: kind menu, "..." menu and the host's actions */}
      <div
        className={cn(
          "flex items-center justify-between pr-3 pl-2",
          EVENT_DETAIL_ROW_HEIGHT_CLASS,
        )}
      >
        <DropdownMenu
          open={kindMenuOpen}
          onOpenChange={(open) => {
            setKindMenuOpen(open);
            if (open) setHoveredOther(false);
          }}
        >
          <DropdownMenuTrigger asChild>
            <button
              type="button"
              // Read-only details show the kind without its menu
              disabled={!onEventChange}
              className={cn(
                "flex h-7 items-center gap-[7px] px-[7px]",
                EVENT_DETAIL_HOVER_BORDER_CLASS,
                !onEventChange &&
                  "hover:border-transparent dark:hover:border-transparent",
                kindMenuOpen && "bg-[#252525] text-white",
              )}
            >
              {EVENT_KIND_LABELS[kind]}
              <ChevronDown
                className={cn(
                  "size-4",
                  kindMenuOpen ? "text-[#595959]" : EVENT_DETAIL_MUTED_CLASS,
                )}
              />
            </button>
          </DropdownMenuTrigger>
          <DropdownMenuContent
            align="start"
            side="left"
            sideOffset={12}
            alignOffset={-4}
            className={cn("min-w-[180px]", EVENT_DETAIL_MENU_CLASS)}
            onMouseLeave={() => setHoveredOther(false)}
            onKeyDown={closeMenuOnEscape(() => setKindMenuOpen(false))}
          >
            <DropdownMenuItem
              className={cn(
                "group/item text-xs text-white focus:bg-[#303030] focus:text-white",
                !hoveredOther && "bg-[#303030]",
              )}
              onClick={() => selectKind(kind)}
              onMouseEnter={() => setHoveredOther(false)}
            >
              <Check className="size-3.5" />
              <span className="flex-1">{EVENT_KIND_LABELS[kind]}</span>
              <EventKindHelpIcon tooltip={EVENT_KIND_TOOLTIPS[kind]} />
            </DropdownMenuItem>
            <DropdownMenuSeparator className="bg-[#303030]" />
            {otherKinds.map((other) => (
              <DropdownMenuItem
                key={other}
                className="group/item text-xs text-white focus:bg-[#303030] focus:text-white pl-8"
                onClick={() => selectKind(other)}
                onMouseEnter={() => setHoveredOther(true)}
              >
                <span className="flex-1">{EVENT_KIND_LABELS[other]}</span>
                <EventKindHelpIcon tooltip={EVENT_KIND_TOOLTIPS[other]} />
              </DropdownMenuItem>
            ))}
          </DropdownMenuContent>
        </DropdownMenu>
        <div className="flex items-center gap-0.5">
          <DropdownMenu>
            <DropdownMenuTrigger asChild>
              <Button
                variant="ghost"
                size="icon"
                aria-label="More actions"
                className={cn(
                  "size-7",
                  EVENT_DETAIL_ICON_BUTTON_CLASS,
                  EVENT_DETAIL_SECONDARY_CLASS,
                )}
              >
                <MoreHorizontal className="size-[18px]" />
              </Button>
            </DropdownMenuTrigger>
            <DropdownMenuContent
              align="start"
              side="left"
              className={cn("min-w-[180px]", EVENT_DETAIL_MENU_CLASS)}
              onKeyDown={stopEscapePropagation}
            >
              <DropdownMenuItem className={EVENT_DETAIL_MENU_ITEM_CLASS}>
                <SquareDashed className="size-3.5" />
                Cut
                <DropdownMenuShortcut className="text-white/40">
                  ⌘X
                </DropdownMenuShortcut>
              </DropdownMenuItem>
              <DropdownMenuItem className={EVENT_DETAIL_MENU_ITEM_CLASS}>
                <TabletSmartphone className="size-3.5" />
                Copy
                <DropdownMenuShortcut className="text-white/40">
                  ⌘C
                </DropdownMenuShortcut>
              </DropdownMenuItem>
              <DropdownMenuItem className={EVENT_DETAIL_MENU_ITEM_CLASS}>
                <Copy className="size-3.5" />
                Duplicate
                <DropdownMenuShortcut className="text-white/40">
                  ⌘D
                </DropdownMenuShortcut>
              </DropdownMenuItem>
              <DropdownMenuSeparator className="bg-[#303030]" />
              <DropdownMenuItem className="text-xs text-[#E56458] focus:!bg-[#DE5551] focus:!text-white focus:[&>svg]:!text-white focus:[&>[data-slot=dropdown-menu-shortcut]]:!text-white">
                <Trash2 className="size-3.5 text-[#E56458]" />
                Delete
                <DropdownMenuShortcut className="text-white/40 tracking-normal">
                  delete
                </DropdownMenuShortcut>
              </DropdownMenuItem>
            </DropdownMenuContent>
          </DropdownMenu>
          {headerActions}
        </div>
      </div>

      {/* Title */}
      <div className="mt-1.5 flex flex-col px-2 pb-2">
        <input
          ref={titleRef}
          {...title.inputProps}
          type="text"
          placeholder="Title"
          readOnly={!onEventChange}
          className={cn(
            "h-[35px] px-[7px] placeholder:text-[#ABABA9] dark:placeholder:text-[#595959]",
            EVENT_DETAIL_INPUT_CLASS,
          )}
        />
      </div>

      <EventDetailDivider />

      {/* When: time and date, then all-day, time zone and repeat */}
      <EventDetailGroup name="when">
        <EventDetailTime event={event} onEventChange={onEventChange} />
        {showOptionRows ? (
          <>
            <div
              className={cn(
                "flex flex-col justify-center",
                EVENT_DETAIL_ROW_HEIGHT_CLASS,
              )}
            >
              <EventDetailAllDay event={event} onEventChange={onEventChange} />
            </div>
            <EventDetailTimezone event={event} onEventChange={onEventChange} />
            <EventDetailRecurrence
              event={event}
              onEventChange={onEventChange}
              onPrevious={onPrevWeek}
              onNext={onNextWeek}
            />
          </>
        ) : (
          <EventDetailOptionsRow onExpand={() => setOptionsExpanded(true)} />
        )}
      </EventDetailGroup>

      <EventDetailDivider />

      {/* Who and where */}
      <EventDetailGroup name="who">
        <EventDetailParticipants event={event} onEventChange={onEventChange} />
        {/* With a call, Notion moves the meeting-note button above it */}
        {event.conference ? (
          <>
            <EventDetailAiNotes event={event} onEventChange={onEventChange} />
            <EventDetailConferencing
              event={event}
              onEventChange={onEventChange}
            />
          </>
        ) : (
          <>
            <EventDetailConferencing
              event={event}
              onEventChange={onEventChange}
            />
            <EventDetailAiNotes event={event} onEventChange={onEventChange} />
          </>
        )}
        <EventDetailLocation event={event} onEventChange={onEventChange} />
      </EventDetailGroup>

      <EventDetailDivider />

      <EventDetailGroup name="links">
        <EventDetailLinks event={event} onEventChange={onEventChange} />
      </EventDetailGroup>

      <EventDetailDivider />

      {/* At least one 35px row, empty or not */}
      <EventDetailGroup name="description" className="min-h-[51px]">
        <EventDetailDescription event={event} onEventChange={onEventChange} />
      </EventDetailGroup>

      <EventDetailDivider />

      {/* Calendar, availability and reminders */}
      <EventDetailGroup name="calendar">
        <EventDetailCalendar event={event} onEventChange={onEventChange} />
        <EventDetailAvailability event={event} onEventChange={onEventChange} />
        <EventDetailReminders event={event} onEventChange={onEventChange} />
      </EventDetailGroup>
    </div>
  );
}

