"use client";

import * as React from "react";
import { MapPin } from "lucide-react";

import { cn } from "@/lib/utils";
import { useCalendarConfig } from "./calendar-provider";
import {
  EVENT_DETAIL_GROUPED_INPUT_CLASS,
  EVENT_DETAIL_HOVER_BORDER_CLASS,
  EVENT_DETAIL_ICON_CLASS,
  EVENT_DETAIL_INPUT_GROUP_CLASS,
  EVENT_DETAIL_TEXT_CLASS,
  EventDetailSection,
} from "./event-detail-parts";
import {
  EVENT_DETAIL_MENU_SECONDARY_CLASS,
  EventDetailSuggestion,
  EventDetailSuggestions,
  HighlightedMatch,
  handleSuggestionKey,
} from "./event-detail-suggestions";
import type {
  DetailedCalendarEvent,
  EventDetailSectionProps,
  LocationSuggestion,
} from "./week-view-types";

/** Width of the suggestions list (Notion: 292px) */
const SUGGESTIONS_WIDTH = 292;

/** Most places listed under the typed text */
const MAX_SUGGESTIONS = 5;

/** A location that is a web address opens itself instead of a map */
const URL_PATTERN = /^https?:\/\/\S+$/i;

/** A row's 32px box, from 8px off the panel's edges, with the icon column at 26px */
const ROW_BOX_CLASS =
  "flex h-8 min-w-0 flex-1 items-center gap-[11px] pr-2 pl-[9px]";

/** The location as it's saved: "Central Park, New York, NY, USA" */
function formatSuggestion(place: LocationSuggestion): string {
  return place.address ? `${place.name}, ${place.address}` : place.name;
}

/** Where the set location opens: itself when it's a link, else Google Maps */
function getLocationHref(location: string): string {
  if (URL_PATTERN.test(location)) return location;
  return `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(location)}`;
}

/**
 * Where the event happens, as in Notion Calendar. Empty: a "Location"
 * field; typing lists the typed text first, then matching places (name
 * over address) from `CalendarProvider`'s `locationSuggestions`. Set: the
 * location, underlined, opening in Google Maps (or itself, for a link);
 * clicking the rest of the row edits it, and clearing the text removes it.
 */
export function EventDetailLocation<
  TEvent extends DetailedCalendarEvent = DetailedCalendarEvent,
>({ event, onEventChange }: EventDetailSectionProps<TEvent>) {
  const { locationSuggestions } = useCalendarConfig();
  const location = event.location ?? "";
  const inputRef = React.useRef<HTMLInputElement>(null);
  const boxRef = React.useRef<HTMLDivElement>(null);
  const listId = React.useId();
  const [editing, setEditing] = React.useState(false);
  const [text, setText] = React.useState(location);
  const [open, setOpen] = React.useState(false);
  const [activeIndex, setActiveIndex] = React.useState(-1);
  /** Set by Escape and by a pick, so the blur that follows doesn't commit */
  const skipCommitRef = React.useRef(false);

  // Follow the event while the field isn't being typed into
  React.useEffect(() => {
    if (!editing) setText(location);
  }, [location, editing]);

  // Focus the field when the set location switches to editing
  React.useEffect(() => {
    if (!editing) return;
    inputRef.current?.focus();
    inputRef.current?.select();
  }, [editing]);

  const trimmed = text.trim();

  /** The typed text, then the places that match it */
  const options = React.useMemo<LocationSuggestion[]>(() => {
    if (!trimmed) return [];
    const q = trimmed.toLowerCase();
    const places = locationSuggestions
      .filter((place) => formatSuggestion(place).toLowerCase().includes(q))
      .filter((place) => formatSuggestion(place) !== trimmed)
      .slice(0, MAX_SUGGESTIONS);
    return [{ name: trimmed }, ...places];
  }, [locationSuggestions, trimmed]);

  const listOpen = open && options.length > 0;

  // The typed text is active, as in Notion
  React.useEffect(() => {
    setActiveIndex(trimmed ? 0 : -1);
  }, [trimmed]);

  const commit = (next: string) => {
    const value = next.trim();
    setText(value);
    if (value === location) return;
    onEventChange?.({ ...event, location: value || undefined });
  };

  const pick = (place: LocationSuggestion) => {
    skipCommitRef.current = true;
    commit(formatSuggestion(place));
    setOpen(false);
    inputRef.current?.blur();
  };

  const handleBlur = () => {
    setOpen(false);
    setEditing(false);
    if (skipCommitRef.current) {
      skipCommitRef.current = false;
      return;
    }
    commit(text);
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === "Escape") {
      e.preventDefault();
      e.stopPropagation();
      skipCommitRef.current = true;
      setText(location);
      inputRef.current?.blur();
      return;
    }
    if (e.key === "Enter" && !listOpen) {
      e.preventDefault();
      inputRef.current?.blur();
      return;
    }
    if (!listOpen) return;
    handleSuggestionKey(e, options.length, activeIndex, setActiveIndex, (i) =>
      pick(options[i]),
    );
  };

  const optionId = (index: number) => `${listId}-option-${index}`;

  if (location && !editing) {
    return (
      <EventDetailSection name="location">
        <div className="flex min-h-[35px] items-center px-2">
          <div
            className={cn(
              "group/location flex min-h-8 min-w-0 flex-1 cursor-text items-start gap-[11px] py-[5px] pr-2 pl-[9px]",
              EVENT_DETAIL_HOVER_BORDER_CLASS,
            )}
            onClick={onEventChange ? () => setEditing(true) : undefined}
          >
            <MapPin className={cn("mt-0.5", EVENT_DETAIL_ICON_CLASS)} />
            <a
              href={getLocationHref(location)}
              target="_blank"
              rel="noreferrer"
              data-testid="event-location-link"
              className={cn(
                "min-w-0 cursor-pointer break-words underline decoration-[#EEEEEE] underline-offset-[3px] group-hover/location:decoration-current dark:decoration-[#262626] dark:group-hover/location:decoration-current",
                EVENT_DETAIL_TEXT_CLASS,
              )}
              onClick={(e) => e.stopPropagation()}
            >
              {location}
            </a>
          </div>
        </div>
      </EventDetailSection>
    );
  }

  return (
    <EventDetailSection name="location">
      <div className="flex min-h-[35px] items-center px-2">
        <div
          ref={boxRef}
          className={cn(ROW_BOX_CLASS, EVENT_DETAIL_INPUT_GROUP_CLASS)}
          onClick={() => inputRef.current?.focus()}
        >
          <MapPin className={EVENT_DETAIL_ICON_CLASS} />
          <input
            ref={inputRef}
            type="text"
            role="combobox"
            aria-label="Location"
            aria-autocomplete="list"
            aria-expanded={listOpen}
            aria-controls={listOpen ? listId : undefined}
            aria-activedescendant={
              listOpen && activeIndex >= 0 ? optionId(activeIndex) : undefined
            }
            data-testid="event-location-input"
            value={text}
            placeholder="Location"
            readOnly={!onEventChange}
            onChange={(e) => {
              setText(e.target.value);
              setOpen(true);
            }}
            onFocus={() => setOpen(true)}
            onBlur={handleBlur}
            onKeyDown={handleKeyDown}
            className={cn(
              "min-w-0 flex-1",
              EVENT_DETAIL_GROUPED_INPUT_CLASS,
              EVENT_DETAIL_TEXT_CLASS,
              "placeholder:text-[#ABABA9] dark:placeholder:text-[#595959]",
            )}
          />
        </div>
      </div>
      {listOpen && (
        <EventDetailSuggestions
          id={listId}
          label="Suggested places"
          anchorRef={boxRef}
          width={SUGGESTIONS_WIDTH}
        >
          {options.map((place, index) => (
            <EventDetailSuggestion
              key={`${index}-${formatSuggestion(place)}`}
              id={optionId(index)}
              active={index === activeIndex}
              onActivate={() => setActiveIndex(index)}
              onSelect={() => pick(place)}
            >
              <span className="flex min-w-0 flex-1 flex-col leading-5">
                <span className="truncate">
                  {index === 0 ? (
                    place.name
                  ) : (
                    <HighlightedMatch text={place.name} query={trimmed} />
                  )}
                </span>
                {place.address && (
                  <span
                    className={cn(
                      "truncate",
                      EVENT_DETAIL_MENU_SECONDARY_CLASS,
                    )}
                  >
                    {place.address}
                  </span>
                )}
              </span>
            </EventDetailSuggestion>
          ))}
        </EventDetailSuggestions>
      )}
    </EventDetailSection>
  );
}

"use client";

import * as React from "react";
import * as ReactDOM from "react-dom";

import { cn } from "@/lib/utils";
import { EVENT_DETAIL_MENU_CLASS } from "./event-detail-parts";

/** Gap between the suggestions and the field they belong to (Notion: 13px) */
const SUGGESTIONS_GAP = 13;

/** Closest the suggestions get to the viewport's edges */
const VIEWPORT_MARGIN = 8;

/** Secondary text in a menu: an email under a name, an address, a hint */
export const EVENT_DETAIL_MENU_SECONDARY_CLASS = "text-[#8B8B8B]";

/** Main text of a menu item */
export const EVENT_DETAIL_MENU_TEXT_CLASS = "text-[#E0E0E0]";

/**
 * Props for EventDetailSuggestions
 */
interface EventDetailSuggestionsProps {
  /** Id of the listbox, set as the field's `aria-controls` */
  id: string;
  /** Accessible name of the list, e.g. "Suggested participants" */
  label: string;
  /** The field's box: the list opens to its left, top-aligned */
  anchorRef: React.RefObject<HTMLElement | null>;
  /** Width in px (Notion: 330 for people, 292 for places) */
  width: number;
  /** Options (`EventDetailSuggestion`) */
  children: React.ReactNode;
  /** Row under the options, after a separator (e.g. "Rooms and resources") */
  footer?: React.ReactNode;
}

interface SuggestionsPosition {
  top: number;
  left: number;
}

/**
 * Places the list left of the field, top-aligned, as Notion does beside
 * its panel. Without room on the left (a narrow window, a popover near the
 * edge), it drops below the field instead.
 */
function getSuggestionsPosition(
  anchor: DOMRect,
  width: number,
): SuggestionsPosition {
  const left = anchor.left - SUGGESTIONS_GAP - width;
  if (left >= VIEWPORT_MARGIN) {
    return { top: anchor.top, left };
  }
  const maxLeft = window.innerWidth - width - VIEWPORT_MARGIN;
  return {
    top: anchor.bottom + 4,
    left: Math.max(VIEWPORT_MARGIN, Math.min(anchor.left, maxLeft)),
  };
}

/**
 * The floating list a details field shows while it's focused (the
 * participants' contacts, the location's places). The field keeps focus and
 * drives it as a combobox (`aria-activedescendant`); the list is a portal in
 * the details' React tree, so the details popover counts presses on it as
 * inside. Rendered only while open.
 */
export function EventDetailSuggestions({
  id,
  label,
  anchorRef,
  width,
  children,
  footer,
}: EventDetailSuggestionsProps) {
  const [position, setPosition] = React.useState<SuggestionsPosition | null>(
    null,
  );

  // Follow the field while the page scrolls or resizes
  React.useLayoutEffect(() => {
    function update() {
      const anchor = anchorRef.current;
      if (!anchor) return;
      setPosition(
        getSuggestionsPosition(anchor.getBoundingClientRect(), width),
      );
    }
    update();
    window.addEventListener("resize", update);
    window.addEventListener("scroll", update, true);
    return () => {
      window.removeEventListener("resize", update);
      window.removeEventListener("scroll", update, true);
    };
  }, [anchorRef, width]);

  if (!position) return null;

  return ReactDOM.createPortal(
    <div
      data-slot="event-detail-suggestions"
      className={cn(
        "fixed z-[9999] overflow-hidden rounded-lg border p-1.5 text-sm font-medium shadow-md",
        EVENT_DETAIL_MENU_CLASS,
      )}
      style={{ top: position.top, left: position.left, width }}
      // Presses keep focus in the field
      onMouseDown={(e) => e.preventDefault()}
    >
      <div id={id} role="listbox" aria-label={label}>
        {children}
      </div>
      {footer && (
        <>
          <div className="-mx-1.5 my-1.5 border-t border-[#303030]" />
          {footer}
        </>
      )}
    </div>,
    document.body,
  );
}

/**
 * Props for EventDetailSuggestion
 */
interface EventDetailSuggestionProps {
  /** Element id, the field's `aria-activedescendant` while active */
  id: string;
  /** Whether the keyboard or pointer is on it */
  active: boolean;
  /** Called when the pointer moves onto it */
  onActivate: () => void;
  /** Picks it */
  onSelect: () => void;
  /** Text and icons */
  children: React.ReactNode;
  className?: string;
}

/**
 * One option of `EventDetailSuggestions`: 31px tall (taller with a second
 * line), with the #303030 highlight inset in the list
 */
export function EventDetailSuggestion({
  id,
  active,
  onActivate,
  onSelect,
  children,
  className,
}: EventDetailSuggestionProps) {
  return (
    <div
      id={id}
      role="option"
      aria-selected={active}
      className={cn(
        "flex min-h-[31px] cursor-default items-center gap-2 rounded-md px-2 py-1",
        EVENT_DETAIL_MENU_TEXT_CLASS,
        active && "bg-[#303030] text-white",
        className,
      )}
      onMouseMove={active ? undefined : onActivate}
      onClick={onSelect}
    >
      {children}
    </div>
  );
}

/**
 * Props for HighlightedMatch
 */
interface HighlightedMatchProps {
  /** Text shown */
  text: string;
  /** What was typed; its first match in `text` stays bright */
  query: string;
}

/**
 * Text with the part that matches the query bright and the rest muted, as
 * Notion's suggestions show matches while typing. Without a query or a
 * match, the whole text keeps the item's color.
 */
export function HighlightedMatch({ text, query }: HighlightedMatchProps) {
  const trimmed = query.trim();
  const start = trimmed
    ? text.toLowerCase().indexOf(trimmed.toLowerCase())
    : -1;
  if (start === -1) {
    return <>{text}</>;
  }
  const end = start + trimmed.length;
  return (
    <>
      <span className={EVENT_DETAIL_MENU_SECONDARY_CLASS}>
        {text.slice(0, start)}
      </span>
      <span className="text-white">{text.slice(start, end)}</span>
      <span className={EVENT_DETAIL_MENU_SECONDARY_CLASS}>
        {text.slice(end)}
      </span>
    </>
  );
}

/**
 * Keyboard handling shared by the suggestion fields: arrows move the active
 * option (wrapping), Enter picks it. Returns whether the key was handled.
 */
export function handleSuggestionKey(
  e: React.KeyboardEvent<HTMLInputElement>,
  count: number,
  activeIndex: number,
  setActiveIndex: (index: number) => void,
  onPick: (index: number) => void,
): boolean {
  if (e.key === "ArrowDown" && count > 0) {
    e.preventDefault();
    setActiveIndex(activeIndex < 0 ? 0 : (activeIndex + 1) % count);
    return true;
  }
  if (e.key === "ArrowUp" && count > 0) {
    e.preventDefault();
    setActiveIndex(activeIndex <= 0 ? count - 1 : activeIndex - 1);
    return true;
  }
  if (e.key === "Enter" && activeIndex >= 0 && activeIndex < count) {
    e.preventDefault();
    onPick(activeIndex);
    return true;
  }
  return false;
}

/**
 * `onKeyDown` for a details menu's content: Escape closes only the menu.
 * The calendar's global Escape would also deselect the event, so the key
 * stops here, and the menu is closed through its `open` state, which works
 * whichever library's own Escape handling runs.
 */
export function closeMenuOnEscape(close: () => void) {
  return (e: React.KeyboardEvent) => {
    if (e.key !== "Escape") return;
    e.stopPropagation();
    close();
  };
}

